#!/usr/bin/env bash
set -euo pipefail

# Git Bash otherwise places GNU tar ahead of Windows tar. GNU tar treats a
# Windows drive prefix as a remote archive host when a child passes native paths.
if [[ "$OSTYPE" == msys* || "$OSTYPE" == cygwin* ]]; then
  export PATH="$(cygpath -u "${SystemRoot:-C:\Windows}")/System32:$PATH"
fi

module="${1:?Expected a repository-relative Luau module path}"
shift
[[ "$module" =~ ^(\.github/integration|config/tools|libraries|validation|fabricator|security|publication)/([a-z-]+/)*[a-z-]+\.luau$ ]] || {
  echo 'Invalid Luau module path' >&2
  exit 1
}
mkdir -p build/luau
adapter="$(mktemp build/luau/invoke.XXXXXXXX.luau)"
trap 'rm -f -- "$adapter"' EXIT
printf '%s\n' '-- Generated by .github/integration/run.sh; edit the source module.' \
  'local Stdio = require("@lune/stdio")' \
  'local function stage(name, opening)' \
  '  Stdio.write(if opening then "::group::Validate / " .. name .. "\n" else "::endgroup::\n")' \
  'end' \
  "local subject = require(\"../../${module%.luau}\")" \
  'if subject.Cases then subject:Run() else subject.Run(stage) end' > "$adapter"
lune run "$adapter" "$@"
